# Run with browser-harness against a local preview; only this slice and isolation contracts.
result=js(r'''(async()=>{
// Baseline renderer contracts; citywide.browser.py covers the rollout default.
const legacyCity=plots=>kit.createCityBuildings(plots,{rollout:false});
const T=await import('three'),slice=await import('./js/world/midrise-slice.js'),kit=await import('./js/world/building-kit.js'),{townhouseMaterials}=await import('./js/world/building-slice-materials.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js');
const check=(v,m)=>{if(!v)throw Error(m)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
check(slice.MIDRISE_LOT_ID==='block--279--49','exact selected ID');check(JSON.stringify(slice.MIDRISE_REPLICATION_IDS)===JSON.stringify(['block--295--80','block--247--93']),'exact two additional IDs');const p=plots.find(p=>p.id===slice.MIDRISE_LOT_ID);check(p&&p.kind==='midrise'&&p.width===14&&p.depth===12&&p.height===24,'existing descriptor');
const g=slice.createMidriseSlice(p),m=townhouseMaterials();check(g.children.length===3&&g.children.every(o=>o.isMesh&&!o.isInstancedMesh),'three renderables');
check(g.children[0].material===m.architecture&&g.children[1].material===m.architecture&&g.children[2].material===m.glass,'exact shared materials');
const maps=new Set;g.children.forEach(o=>Object.values(o.material).forEach(v=>{if(v?.isTexture)maps.add(v)}));check(maps.size===4,'same four maps');
let triangles=0;for(let k=0;k<3;k++){const o=g.children[k],a=o.geometry.attributes;check(o.castShadow===(k===0)&&o.receiveShadow&&o.frustumCulled,'render policy');check(o.geometry.boundingBox&&o.geometry.boundingSphere,'bounds');triangles+=a.position.count/3;for(const [key,size]of [['position',3],['normal',3],['uv',2],['aSurface',1],['color',3]])check(a[key]?.count===a.position.count&&a[key].itemSize===size,`attribute ${key}`);for(let i=0;i<a.position.count;i++){const x=a.position.getX(i),y=a.position.getY(i),z=a.position.getZ(i);check(Math.abs(x)<=p.width/2+.0001&&Math.abs(z)<=p.depth/2+.0001&&y>=0&&y<=p.height+.0001,'footprint/height');check(Math.abs(new T.Vector3().fromBufferAttribute(a.normal,i).length()-1)<.0001,'normal');}if(k!==2)for(let i=0;i<a.position.count;i+=6){const d=new T.Vector3().fromBufferAttribute(a.position,i).distanceTo(new T.Vector3().fromBufferAttribute(a.position,i+1)),uv=new T.Vector2().fromBufferAttribute(a.uv,i).distanceTo(new T.Vector2().fromBufferAttribute(a.uv,i+1));check(Math.abs(d-uv)<.0001,'metric UV');}}
check(triangles<=7000,'triangle budget');check(g.userData.recipe.floors>=4&&g.userData.recipe.floors<=8&&g.userData.recipe.roof==='parapet','midrise recipe');
const openings=g.userData.openings;check(openings.some(o=>o.type==='door'&&o.w<=1.8&&o.h<=3),'human entry');check(openings.every(o=>o.reveal>=.25),'real recess');check(!g.userData.lods,'no LOD');
const fp=o=>{const a=[];o.traverse(m=>{if(m.isMesh)a.push({name:m.name,cast:m.castShadow,attributes:Object.fromEntries(Object.entries(m.geometry.attributes).map(([k,v])=>[k,Array.from(v.array)])),instances:m.instanceMatrix?Array.from(m.instanceMatrix.array):null,colors:m.instanceColor?Array.from(m.instanceColor.array):null})});return JSON.stringify(a)};
const city=legacyCity(plots),selected=city.getObjectByName(p.id);check(selected?.userData.archetype==='midrise-slice','integration');check(city.children.filter(o=>o.userData.archetype==='midrise-slice').length===2,'approved slice plus local batch');
const others=new T.Group();city.children.filter(o=>o.userData.archetype!=='midrise-slice').forEach(o=>others.add(o.clone()));check(fp(others)===fp(legacyCity(plots.filter(o=>![p.id,...slice.MIDRISE_REPLICATION_IDS].includes(o.id)))),'all other buildings/control townhouses unchanged');
check(fp(g)===fp(selected),'approved geometry unchanged');check(fp(g)===fp(slice.createMidriseSlice(p)),'determinism');let disposed=0;const replication=city.getObjectByName('midrise-replication');check(replication?.children.length===3,'two new buildings merged into three meshes');check(JSON.stringify(replication.userData.plotIds)===JSON.stringify(slice.MIDRISE_REPLICATION_IDS),'exact allowlist');const replicas=slice.MIDRISE_REPLICATION_IDS.map(id=>plots.find(p=>p.id===id));check(replicas.every(p=>p&&p.kind==='midrise'&&p.width===14&&p.depth===12),'replica descriptors');check(replicas[0].height===27&&replicas[1].height===24,'height caps');check(new Set(replication.userData.recipes.map(r=>JSON.stringify(r))).size===2,'controlled recipe variety');check(JSON.stringify(replication.userData.recipes)===JSON.stringify(replicas.map(slice.midriseRecipe)),'deterministic recipes/palettes');let groupTriangles=triangles;
for(let k=0;k<3;k++){const actual=replication.children[k];check(actual.castShadow===(k===0)&&actual.receiveShadow,'merged shadow policy');groupTriangles+=actual.geometry.attributes.position.count/3;let offset=0;for(const p of replicas){const h=slice.createMidriseSlice(p),source=h.children[k].geometry;for(const [key,attribute]of Object.entries(source.attributes)){const merged=actual.geometry.attributes[key];check(merged?.itemSize===attribute.itemSize,'preserve merge attributes');for(let i=0;i<attribute.array.length;i++){let value=attribute.array[i];if(key==='position'){if(i%3===0)value+=p.x-replication.position.x;if(i%3===2)value+=p.z-replication.position.z;}check(Math.abs(merged.array[offset*attribute.itemSize+i]-value)<.00001,'geometry/UV/color preserved');}}offset+=source.attributes.position.count;h.children.forEach(m=>m.geometry.dispose());}check(offset===actual.geometry.attributes.position.count,'no duplicates');}check(groupTriangles<=15000,'three-building triangle budget');
replication.children.forEach(o=>{check(o.material===m.architecture||o.material===m.glass,'shared resources');check(o.frustumCulled&&o.geometry.boundingBox&&o.geometry.boundingSphere,'batch bounds/culling');o.geometry.addEventListener('dispose',()=>disposed++);});selected.children.forEach(m=>m.geometry.addEventListener('dispose',()=>disposed++));city.userData.dispose();check(disposed===6,'dispose all six geometries');let rejected=false;try{slice.createMidriseSlice({...p,height:2})}catch(e){rejected=e instanceof TypeError}check(rejected,'descriptor validation');
return {pass:true,id:p.id,plot:p,renderables:6,triangles:groupTriangles,materials:2,maps:maps.size,recipes:[g.userData.recipe,...replication.userData.recipes],openings:openings.length};})()''')
print(result)
assert isinstance(result,dict) and result.get('pass'),result
